		  printf ("x86 ISA used: ");
		  if (datasz != 4)
		    printf (_("<corrupt length: %#x> "), datasz);
		  else
		    decode_x86_isa (byte_get (ptr, 4));
		  goto next;

		case GNU_PROPERTY_X86_ISA_1_NEEDED:
		  printf ("x86 ISA needed: ");
		  if (datasz != 4)
		    printf (_("<corrupt length: %#x> "), datasz);
		  else
		    decode_x86_isa (byte_get (ptr, 4));
		  goto next;

		case GNU_PROPERTY_X86_FEATURE_1_AND:
		  printf ("x86 feature: ");
		  if (datasz != 4)
		    printf (_("<corrupt length: %#x> "), datasz);
		  else
		    decode_x86_feature (type, byte_get (ptr, 4));
		  goto next;

		default:
		  break;
		}
	    }
	}
      else
	{
	  switch (type)
