symcount = bfd_canonicalize_symtab (abfd, syms);
if (symcount < 0)
    goto error_return;
if (symcount == 0)
    /* We return 0 above when storage is 0.  Exit in the same state
       here, so as to not complicate callers with having to deal with
       freeing memory for zero symcount.  */
