      || (section->flags & SEC_THREAD_LOCAL) == 0
      || segment->p_type == PT_TLS)
    return section->size;
}

reduced_function_code.segment_end:
static inline bfd_vma
segment_end (Elf_Internal_Phdr *segment, bfd_vma start)
{
Elf_Internal_Phdr *segment
