	    for (i = nesting_level; i-- != 0; )
	      if (nested_funcs[i].func)
		{
		  func->caller_func = nested_funcs[i].func;
		  break;
		}
nested_funcs[nesting_level].func = func;
func = NULL;
var = (struct varinfo *) bfd_zalloc (abfd, amt);
if (var == NULL)
		goto fail;
var->tag = abbrev->tag;
var->stack = true;
var->prev_var = unit->variable_table;
unit->variable_table = var;
var->unit_offset = current_offset;
var = NULL;
struct attribute attr;
info_ptr = read_attribute (&attr, &abbrev->attrs[i],
				     unit, info_ptr, info_ptr_end);
unit->function_table = reverse_funcinfo_list (unit->function_table);
unit->variable_table = reverse_varinfo_list (unit->variable_table);
info_ptr = unit->first_child_die_ptr;
current_offset = info_ptr - unit->info_ptr_unit;
abbrev = lookup_abbrev (abbrev_number, unit->abbrevs);
func = NULL;
var = NULL;
func = last_func->prev_func;
func = lookup_func_by_offset (current_offset, unit->function_table);
if (func == NULL)
	    goto fail;
last_func = func;
var = last_var->prev_var;
var = lookup_var_by_offset (current_offset, unit->variable_table);
if (var == NULL)
	    goto fail;
last_var = var;
info_ptr = read_attribute (&attr, &abbrev->attrs[i],
				     unit, info_ptr, info_ptr_end);
if (func)
	    {
	      switch (attr.name)
		{
		case DW_AT_call_file:
		  if (is_int_form (&attr))
		    func->caller_file = concat_filename (unit->line_table,
							 attr.u.val);
		  break;

		case DW_AT_call_line:
		  if (is_int_form (&attr))
		    func->caller_line = attr.u.val;
		  break;

		case DW_AT_abstract_origin:
		case DW_AT_specification:
		  if (is_int_form (&attr)
		      && !find_abstract_instance (unit, &attr, 0,
						  &func->name,
						  &func->is_linkage,
						  &func->file,
						  &func->line))
		    goto fail;
		  break;

		case DW_AT_name:
		  /* Prefer DW_AT_MIPS_linkage_name or DW_AT_linkage_name
		     over DW_AT_name.  */
		  if (func->name == NULL && is_str_form (&attr))
		    {
		      func->name = attr.u.str;
		      if (mangle_style (unit->lang) == 0)
			func->is_linkage = true;
		    }
		  break;

		case DW_AT_linkage_name:
		case DW_AT_MIPS_linkage_name:
		  /* PR 16949:  Corrupt debug info can place
		     non-string forms into these attributes.  */
		  if (is_str_form (&attr))
		    {
		      func->name = attr.u.str;
		      func->is_linkage = true;
		    }
		  break;

		case DW_AT_low_pc:
		  if (is_int_form (&attr))
		    low_pc = attr.u.val;
		  break;

		case DW_AT_high_pc:
		  if (is_int_form (&attr))
		    {
		      high_pc = attr.u.val;
		      high_pc_relative = attr.form != DW_FORM_addr;
		    }
		  break;

		case DW_AT_ranges:
		  if (is_int_form (&attr)
		      && !read_rangelist (unit, &func->arange,
					  &unit->file->trie_root, attr.u.val))
