	    {
	      switch (attr.name)
		{
		case DW_AT_specification:
		  if (is_int_form (&attr) && attr.u.val)
		    {
		      bool is_linkage;
		      if (!find_abstract_instance (unit, &attr, 0,
						   &var->name,
						   &is_linkage,
						   &var->file,
						   &var->line))
			{
			  _bfd_error_handler (_("DWARF error: could not find "
						"variable specification "
						"at offset 0x%lx"),
					      (unsigned long) attr.u.val);
			  break;
			}
		    }
		  break;

		case DW_AT_name:
		  if (is_str_form (&attr))
		    var->name = attr.u.str;
		  break;

		case DW_AT_decl_file:
		  if (is_int_form (&attr))
		    {
		      free (var->file);
		      var->file = concat_filename (unit->line_table,
						   attr.u.val);
		    }
		  break;

		case DW_AT_decl_line:
		  if (is_int_form (&attr))
		    var->line = attr.u.val;
		  break;

		case DW_AT_external:
		  if (is_int_form (&attr) && attr.u.val != 0)
		    var->stack = false;
		  break;

		case DW_AT_location:
		  switch (attr.form)
		    {
		    case DW_FORM_block:
		    case DW_FORM_block1:
		    case DW_FORM_block2:
		    case DW_FORM_block4:
		    case DW_FORM_exprloc:
		      if (attr.u.blk->data != NULL
			  && *attr.u.blk->data == DW_OP_addr)
			{
			  var->stack = false;

			  /* Verify that DW_OP_addr is the only opcode in the
			     location, in which case the block size will be 1
			     plus the address size.  */
			  /* ??? For TLS variables, gcc can emit
			     DW_OP_addr <addr> DW_OP_GNU_push_tls_address
			     which we don't handle here yet.  */
			  if (attr.u.blk->size == unit->addr_size + 1U)
			    var->addr = bfd_get (unit->addr_size * 8,
						 unit->abfd,
						 attr.u.blk->data + 1);
			}
		      break;

		    default:
		      break;
		    }
		  break;

		default:
		  break;
		}
	    }
if (func && high_pc != 0)
	{
	  if (!arange_add (unit, &func->arange, &unit->file->trie_root,
			   low_pc, high_pc))
	    goto fail;
	}
unit->function_table = reverse_funcinfo_list (unit->function_table);
unit->variable_table = reverse_varinfo_list (unit->variable_table);
}

reduced_function_code.read_indexed_address:
static uint64_t
read_indexed_address (uint64_t idx, struct comp_unit *unit)
{
struct dwarf2_debug *stash = unit->stash;
struct dwarf2_debug_file *file = unit->file;
bfd_byte *info_ptr;
size_t offset;

struct comp_unit *unit
if (!read_section (unit->abfd, &stash->debug_sections[debug_addr],
		     file->syms, 0,
		     &file->dwarf_addr_buffer, &file->dwarf_addr_size))
    return 0;
if (_bfd_mul_overflow (idx, unit->addr_size, &offset))
    return 0;
offset += unit->dwarf_addr_offset;
if (offset < unit->dwarf_addr_offset
      || offset > file->dwarf_addr_size
      || file->dwarf_addr_size - offset < unit->addr_size)
    return 0;
info_ptr = file->dwarf_addr_buffer + offset;
if (unit->addr_size == 4)
    return bfd_get_32 (unit->abfd, info_ptr);
  else if (unit->addr_size == 8)
    return bfd_get_64 (unit->abfd, info_ptr);
  else
    return 0;
}

reduced_function_code.bfd_init_section_decompress_status:
bool
bfd_init_section_decompress_status (bfd *abfd, sec_ptr sec)
{
bfd_size_type uncompressed_size;
unsigned int uncompressed_alignment_power = 0;
unsigned int ch_type;

ch_type = 0;
if (!bfd_check_compression_header (abfd, header, sec,
					  &ch_type,
					  &uncompressed_size,
					  &uncompressed_alignment_power))
    {
      bfd_set_error (bfd_error_wrong_format);
      return false;
    }
sec->compress_status = (ch_type == ELFCOMPRESS_ZSTD
			  ? DECOMPRESS_SECTION_ZSTD : DECOMPRESS_SECTION_ZLIB);
}

reduced_function_code.bfd_mach_o_get_synthetic_symtab:
long
bfd_mach_o_get_synthetic_symtab (bfd *abfd,
				 long symcount ATTRIBUTE_UNUSED,
				 asymbol **syms ATTRIBUTE_UNUSED,
				 long dynsymcount ATTRIBUTE_UNUSED,
				 asymbol **dynsyms ATTRIBUTE_UNUSED,
				 asymbol **ret)
{
bfd_mach_o_data_struct *mdata = bfd_mach_o_get_data (abfd);
bfd_mach_o_dysymtab_command *dysymtab = mdata->dysymtab;
bfd_mach_o_symtab_command *symtab = mdata->symtab;
asymbol *s;
char * s_start;
unsigned long count, i, j, n;
size_t size;
char *names;
const char stub [] = "$stub";
bfd_mach_o_section *sec = mdata->sections[i];
unsigned int first, last;
bfd_vma addr;
unsigned int entry_size;

if (dysymtab == NULL || dysymtab->nindirectsyms == 0
      || symtab == NULL || symtab->symbols == NULL)
    return 0;
count = dysymtab->nindirectsyms;
size = 0;
for (j = 0; j < count; j++)
    {
      unsigned int isym = dysymtab->indirect_syms[j];
      const char *str;

      /* Some indirect symbols are anonymous.  */
      if (isym < symtab->nsyms
	  && (str = symtab->symbols[isym].symbol.name) != NULL)
	{
	  /* PR 17512: file: f5b8eeba.  */
	  size += strnlen (str, symtab->strsize - (str - symtab->strtab));
	  size += sizeof (stub);
	}
    }
s_start = bfd_malloc (size + count * sizeof (asymbol));
s = *ret = (asymbol *) s_start;
if (s == NULL)
    return -1;
names = (char *) (s + count);
n = 0;
switch (sec->flags & BFD_MACH_O_SECTION_TYPE_MASK)
	{
	case BFD_MACH_O_S_NON_LAZY_SYMBOL_POINTERS:
	case BFD_MACH_O_S_LAZY_SYMBOL_POINTERS:
	case BFD_MACH_O_S_SYMBOL_STUBS:
	  /* Only these sections have indirect symbols.  */
	  first = sec->reserved1;
	  last = first + bfd_mach_o_section_get_nbr_indirect (abfd, sec);
	  addr = sec->addr;
	  entry_size = bfd_mach_o_section_get_entry_size (abfd, sec);

	  /* PR 17512: file: 08e15eec.  */
	  if (first >= count || last > count || first > last)
	    goto fail;

	  for (j = first; j < last; j++)
	    {
	      unsigned int isym = dysymtab->indirect_syms[j];
	      const char *str;
	      size_t len;

	      if (isym < symtab->nsyms
		  && (str = symtab->symbols[isym].symbol.name) != NULL)
		{
		  /* PR 17512: file: 04d64d9b.  */
		  if (n >= count)
		    goto fail;
		  len = strnlen (str, symtab->strsize - (str - symtab->strtab));
		  /* PR 17512: file: 47dfd4d2, 18f340a4.  */
		  if (size < len + sizeof (stub))
		    goto fail;
		  memcpy (names, str, len);
		  memcpy (names + len, stub, sizeof (stub));
		  s->name = names;
		  names += len + sizeof (stub);
		  size -= len + sizeof (stub);
		  s->the_bfd = symtab->symbols[isym].symbol.the_bfd;
		  s->flags = BSF_GLOBAL | BSF_SYNTHETIC;
		  s->section = sec->bfdsection;
		  s->value = addr - sec->addr;
		  s->udata.p = NULL;
		  s++;
		  n++;
		}
	      addr += entry_size;
	    }
	  break;
	default:
	  break;
	}
return n;
free (s_start);
}
